SET LOCAL ROLE everydayai_owner;
CREATE TABLE agent_runtime_scheduler_operation_intents ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), task_id UUID NOT NULL, org_id UUID NOT NULL REFERENCES organizations(id) ON DELETE RESTRICT, user_id UUID REFERENCES users(id) ON DELETE RESTRICT, session_id UUID NOT NULL REFERENCES agent_runtime_sessions(id) ON DELETE RESTRICT, run_id UUID NOT NULL REFERENCES agent_runs(id) ON DELETE RESTRICT, action_id UUID NOT NULL REFERENCES agent_actions(id) ON DELETE RESTRICT, attempt_id UUID NOT NULL REFERENCES agent_action_attempts(id) ON DELETE RESTRICT, policy_receipt_id UUID NOT NULL REFERENCES agent_policy_receipts(id) ON DELETE RESTRICT, dispatch_intent_id UUID NOT NULL REFERENCES agent_action_dispatch_intents(id) ON DELETE RESTRICT, operation TEXT NOT NULL CHECK (operation IN ('create','update','pause','resume','delete')), expected_state_version BIGINT NOT NULL CHECK (expected_state_version >= 0), request_hash TEXT NOT NULL CHECK (request_hash ~ '^[0-9a-f]{64}$'), payload_hash TEXT NOT NULL CHECK (payload_hash ~ '^[0-9a-f]{64}$'), idempotency_key TEXT NOT NULL CHECK (length(btrim(idempotency_key)) BETWEEN 1 AND 300), execution_token UUID NOT NULL, tenant_kill_epoch BIGINT NOT NULL CHECK (tenant_kill_epoch >= 0), provider_kill_epoch BIGINT NOT NULL CHECK (provider_kill_epoch >= 0), capability_kill_epoch BIGINT NOT NULL CHECK (capability_kill_epoch >= 0), provider_revision TEXT, capability_revision TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(), UNIQUE (org_id, idempotency_key), UNIQUE (task_id, idempotency_key) );
CREATE TABLE agent_runtime_scheduler_operation_receipts ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), intent_id UUID NOT NULL UNIQUE REFERENCES agent_runtime_scheduler_operation_intents(id) ON DELETE RESTRICT, outcome TEXT NOT NULL CHECK (outcome IN ('committed','cancelled','cas_conflict')), task_id UUID NOT NULL, state_version BIGINT NOT NULL CHECK (state_version >= 0), task_snapshot JSONB NOT NULL CHECK (jsonb_typeof(task_snapshot) = 'object'), response_hash TEXT NOT NULL CHECK (response_hash ~ '^[0-9a-f]{64}$'), created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp() );
CREATE TABLE agent_runtime_scheduler_cancel_gates ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id UUID NOT NULL REFERENCES organizations(id) ON DELETE RESTRICT, action_id UUID NOT NULL REFERENCES agent_actions(id) ON DELETE RESTRICT, attempt_id UUID NOT NULL REFERENCES agent_action_attempts(id) ON DELETE RESTRICT, request_hash TEXT NOT NULL CHECK (request_hash ~ '^[0-9a-f]{64}$'), idempotency_key TEXT NOT NULL CHECK (length(btrim(idempotency_key)) BETWEEN 1 AND 300), reason TEXT NOT NULL CHECK (length(btrim(reason)) BETWEEN 1 AND 200), proof_hash TEXT NOT NULL CHECK (proof_hash ~ '^[0-9a-f]{64}$'), created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(), UNIQUE (org_id, idempotency_key) );
CREATE INDEX idx_runtime_scheduler_intents_recovery ON agent_runtime_scheduler_operation_intents(attempt_id, created_at DESC);
ALTER TABLE agent_runtime_scheduler_operation_intents ENABLE ROW LEVEL SECURITY;
ALTER TABLE agent_runtime_scheduler_operation_intents FORCE ROW LEVEL SECURITY;
ALTER TABLE agent_runtime_scheduler_operation_receipts ENABLE ROW LEVEL SECURITY;
ALTER TABLE agent_runtime_scheduler_operation_receipts FORCE ROW LEVEL SECURITY;
ALTER TABLE agent_runtime_scheduler_cancel_gates ENABLE ROW LEVEL SECURITY;
ALTER TABLE agent_runtime_scheduler_cancel_gates FORCE ROW LEVEL SECURITY;
CREATE POLICY agent_runtime_scheduler_intents_owner_all ON agent_runtime_scheduler_operation_intents FOR ALL TO everydayai_owner USING (TRUE) WITH CHECK (TRUE);
CREATE POLICY agent_runtime_scheduler_receipts_owner_all ON agent_runtime_scheduler_operation_receipts FOR ALL TO everydayai_owner USING (TRUE) WITH CHECK (TRUE);
CREATE POLICY agent_runtime_scheduler_cancel_gates_owner_all ON agent_runtime_scheduler_cancel_gates FOR ALL TO everydayai_owner USING (TRUE) WITH CHECK (TRUE);
REVOKE ALL ON TABLE agent_runtime_scheduler_operation_intents, agent_runtime_scheduler_operation_receipts, agent_runtime_scheduler_cancel_gates FROM PUBLIC, everydayai_runtime, everydayai_wecom_runtime, everydayai_worker, everydayai_sync, everydayai, everydayai_agent_runtime_worker;
CREATE FUNCTION _runtime_scheduler_immutable_fact() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$ BEGIN RAISE EXCEPTION 'RUNTIME_SCHEDULER_FACT_IMMUTABLE' USING ERRCODE = '55000';
END;
$$;
CREATE TRIGGER scheduler_operation_intent_immutable BEFORE UPDATE OR DELETE ON agent_runtime_scheduler_operation_intents FOR EACH ROW EXECUTE FUNCTION _runtime_scheduler_immutable_fact();
CREATE TRIGGER scheduler_operation_receipt_immutable BEFORE UPDATE OR DELETE ON agent_runtime_scheduler_operation_receipts FOR EACH ROW EXECUTE FUNCTION _runtime_scheduler_immutable_fact();
CREATE TRIGGER scheduler_cancel_gate_immutable BEFORE UPDATE OR DELETE ON agent_runtime_scheduler_cancel_gates FOR EACH ROW EXECUTE FUNCTION _runtime_scheduler_immutable_fact();
CREATE FUNCTION _runtime_scheduler_actor_allowed(p_org_id UUID,p_user_id UUID,p_push_to_others BOOLEAN DEFAULT FALSE) RETURNS BOOLEAN LANGUAGE SQL STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$ SELECT EXISTS (SELECT 1 FROM org_members member JOIN org_member_assignments assignment ON assignment.org_id=member.org_id AND assignment.user_id=member.user_id AND assignment.is_primary JOIN org_positions position ON position.id=assignment.position_id AND position.org_id=assignment.org_id LEFT JOIN org_departments department ON department.id=assignment.department_id AND department.org_id=assignment.org_id WHERE member.org_id=p_org_id AND member.user_id=p_user_id AND member.status='active' AND (position.code IN ('boss','vp') OR department.type IN ('ops','finance','warehouse','service','design','hr')) AND (NOT p_push_to_others OR position.code IN ('boss','vp') OR (position.code IN ('manager','deputy') AND department.type IN ('ops','finance','warehouse','service','design','hr')))); $$;
CREATE FUNCTION _runtime_scheduler_operation_allowed(p_org_id UUID,p_user_id UUID,p_operation TEXT,p_task_owner_id UUID) RETURNS BOOLEAN LANGUAGE SQL STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$ SELECT COALESCE((SELECT CASE WHEN actor_position.code='boss' THEN TRUE WHEN actor_position.code='vp' THEN actor_assignment.data_scope='all' OR (actor_assignment.data_scope='dept_subtree' AND owner_member.user_id IS NOT NULL AND owner_assignment.department_id=ANY(COALESCE(actor_assignment.data_scope_dept_ids,ARRAY[]::UUID[]))) WHEN actor_position.code='manager' THEN actor_department.type IN ('ops','finance','warehouse','service','design','hr') AND owner_member.user_id IS NOT NULL AND owner_assignment.department_id=actor_assignment.department_id WHEN actor_position.code IN ('deputy','member') THEN actor_department.type IN ('ops','finance','warehouse','service','design','hr') AND p_task_owner_id=p_user_id ELSE FALSE END FROM org_members actor_member JOIN org_member_assignments actor_assignment ON actor_assignment.org_id=actor_member.org_id AND actor_assignment.user_id=actor_member.user_id AND actor_assignment.is_primary JOIN org_positions actor_position ON actor_position.id=actor_assignment.position_id AND actor_position.org_id=actor_assignment.org_id LEFT JOIN org_departments actor_department ON actor_department.id=actor_assignment.department_id AND actor_department.org_id=actor_assignment.org_id LEFT JOIN org_member_assignments owner_assignment ON owner_assignment.org_id=p_org_id AND owner_assignment.user_id=p_task_owner_id AND owner_assignment.is_primary LEFT JOIN org_members owner_member ON owner_member.org_id=owner_assignment.org_id AND owner_member.user_id=owner_assignment.user_id AND owner_member.status='active' WHERE actor_member.org_id=p_org_id AND actor_member.user_id=p_user_id AND actor_member.status='active' AND p_operation IN ('create','update','pause','resume','delete')),FALSE); $$;
CREATE FUNCTION _runtime_scheduler_push_target_allowed(p_org_id UUID,p_user_id UUID,p_target JSONB,p_depth INTEGER DEFAULT 0) RETURNS BOOLEAN LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$ DECLARE target_type TEXT; target_user UUID; item JSONB; BEGIN IF p_depth NOT BETWEEN 0 AND 4 OR jsonb_typeof(p_target)<>'object' THEN RETURN FALSE; END IF; target_type:=p_target->>'type'; IF target_type='web' THEN BEGIN target_user:=(p_target->>'user_id')::UUID; EXCEPTION WHEN invalid_text_representation THEN RETURN FALSE; END; IF NOT EXISTS (SELECT 1 FROM org_members WHERE org_id=p_org_id AND user_id=target_user AND status='active') THEN RETURN FALSE; END IF; RETURN target_user=p_user_id OR _runtime_scheduler_actor_allowed(p_org_id,p_user_id,TRUE); ELSIF target_type='wecom_user' THEN IF NULLIF(btrim(p_target->>'wecom_userid'),'') IS NULL OR NOT EXISTS (SELECT 1 FROM wecom_user_mappings mapping JOIN org_members member ON member.org_id=mapping.org_id AND member.user_id=mapping.user_id AND member.status='active' WHERE mapping.org_id=p_org_id AND mapping.wecom_userid=btrim(p_target->>'wecom_userid')) THEN RETURN FALSE; END IF; IF EXISTS (SELECT 1 FROM wecom_user_mappings WHERE org_id=p_org_id AND user_id=p_user_id AND wecom_userid=btrim(p_target->>'wecom_userid')) THEN RETURN TRUE; END IF; RETURN _runtime_scheduler_actor_allowed(p_org_id,p_user_id,TRUE); ELSIF target_type='wecom_group' THEN RETURN _runtime_scheduler_actor_allowed(p_org_id,p_user_id,TRUE) AND NULLIF(btrim(p_target->>'chatid'),'') IS NOT NULL AND EXISTS (SELECT 1 FROM wecom_chat_targets WHERE org_id=p_org_id AND chatid=btrim(p_target->>'chatid') AND is_active); ELSIF target_type='multi' THEN IF NOT _runtime_scheduler_actor_allowed(p_org_id,p_user_id,TRUE) OR jsonb_typeof(p_target->'targets')<>'array' OR jsonb_array_length(p_target->'targets') NOT BETWEEN 1 AND 20 THEN RETURN FALSE; END IF; FOR item IN SELECT value FROM jsonb_array_elements(p_target->'targets') LOOP IF NOT _runtime_scheduler_push_target_allowed(p_org_id,p_user_id,item,p_depth+1) THEN RETURN FALSE; END IF; END LOOP; RETURN TRUE; END IF; RETURN FALSE; END; $$;
CREATE FUNCTION _runtime_scheduler_payload_safe(p_payload JSONB) RETURNS BOOLEAN LANGUAGE SQL IMMUTABLE SET search_path = pg_catalog, public AS $$ SELECT jsonb_typeof(COALESCE(p_payload, '{}'::JSONB)) = 'object' AND COALESCE(p_payload::TEXT, '') !~* '(secret|token|password|credential|api[_-]?key|authorization|cookie|private[_-]?key)';
$$;
CREATE FUNCTION _runtime_scheduler_payload_valid(p_operation TEXT, p_payload JSONB) RETURNS BOOLEAN LANGUAGE plpgsql STABLE SET search_path = pg_catalog, public AS $$ DECLARE value JSONB := COALESCE(p_payload, '{}'::JSONB); schedule_keys TEXT[] := ARRAY['schedule_type','cron_expr','run_at','weekdays','day_of_month','next_run_at','timezone']; schedule_change BOOLEAN; BEGIN IF NOT _runtime_scheduler_payload_safe(value) OR (p_operation IN ('pause','resume','delete') AND value<>'{}'::JSONB) OR value - ARRAY[ 'name','prompt','cron_expr','timezone','push_target','template_file', 'max_credits','retry_count','timeout_sec','schedule_type','run_at', 'weekdays','day_of_month','next_run_at' ]::TEXT[] <> '{}'::JSONB OR value ?| ARRAY[ 'id','org_id','user_id','runtime_action_id','runtime_attempt_id', 'runtime_request_hash','runtime_state_version','runtime_idempotency_key', 'created_at','updated_at','last_summary','last_result','run_count', 'consecutive_failures','last_run_at' ] THEN RETURN FALSE; END IF; IF (value ? 'name' AND length(btrim(value->>'name')) NOT BETWEEN 1 AND 100) OR (value ? 'prompt' AND length(value->>'prompt') NOT BETWEEN 1 AND 5000) OR (value ? 'timezone' AND (length(btrim(value->>'timezone')) NOT BETWEEN 1 AND 50 OR NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name=value->>'timezone'))) OR (value ? 'push_target' AND jsonb_typeof(value->'push_target') <> 'object') THEN RETURN FALSE; END IF; BEGIN IF (value ? 'max_credits' AND (value->>'max_credits')::INTEGER NOT BETWEEN 1 AND 1000) OR (value ? 'retry_count' AND (value->>'retry_count')::INTEGER NOT BETWEEN 0 AND 5) OR (value ? 'timeout_sec' AND (value->>'timeout_sec')::INTEGER NOT BETWEEN 10 AND 600) THEN RETURN FALSE; END IF; IF value ? 'next_run_at' THEN PERFORM (value->>'next_run_at')::TIMESTAMPTZ; END IF; EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR numeric_value_out_of_range THEN RETURN FALSE; END; schedule_change := p_operation='create' OR (p_operation='update' AND value ?| schedule_keys); IF p_operation='create' AND (NOT (value ? 'name') OR NOT (value ? 'prompt') OR NOT (value ? 'push_target')) THEN RETURN FALSE; END IF; IF schedule_change AND (NOT (value ? 'schedule_type') OR NOT (value ? 'timezone') OR NOT (value ? 'next_run_at') OR NULLIF(value->>'next_run_at','') IS NULL) THEN RETURN FALSE; END IF; IF value ? 'schedule_type' AND value->>'schedule_type' NOT IN ('once','daily','weekly','monthly','cron') THEN RETURN FALSE; END IF; IF value ? 'schedule_type' AND ((value->>'schedule_type'='once' AND (NULLIF(value->>'run_at','') IS NULL OR (value->>'run_at')::TIMESTAMPTZ IS DISTINCT FROM (value->>'next_run_at')::TIMESTAMPTZ)) OR (value->>'schedule_type'<>'once' AND NULLIF(btrim(value->>'cron_expr'),'') IS NULL)) THEN RETURN FALSE; END IF; RETURN TRUE; EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow THEN RETURN FALSE; END; $$;
CREATE FUNCTION _runtime_scheduler_control_context( p_attempt_id UUID, p_action_id UUID, p_run_id UUID, p_org_id UUID, p_user_id UUID, p_scope_kind TEXT, p_scope_id TEXT, p_request_hash TEXT, p_execution_token UUID, p_attempt_state_version BIGINT, p_dispatch_intent_id UUID ) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$ DECLARE a agent_action_attempts%ROWTYPE;
x agent_actions%ROWTYPE;
r agent_runs%ROWTYPE;
s agent_runtime_sessions%ROWTYPE;
d agent_action_dispatch_intents%ROWTYPE;
p agent_policy_receipts%ROWTYPE;
f agent_runtime_owner_fences%ROWTYPE;
gate JSONB;
BEGIN PERFORM _assert_agent_runtime_actor(TRUE);
IF p_attempt_id IS NULL OR p_action_id IS NULL OR p_run_id IS NULL OR p_org_id IS NULL OR p_user_id IS NULL OR p_execution_token IS NULL OR p_attempt_state_version IS NULL OR p_request_hash !~ '^[0-9a-f]{64}$' OR p_scope_kind NOT IN ('user','channel','system') OR NULLIF(btrim(p_scope_id), '') IS NULL OR p_dispatch_intent_id IS NULL THEN RAISE EXCEPTION 'RUNTIME_SCHEDULER_CONTEXT_INVALID' USING ERRCODE = '22023';
END IF;
SELECT * INTO a FROM agent_action_attempts WHERE id = p_attempt_id FOR UPDATE;
SELECT * INTO x FROM agent_actions WHERE id = p_action_id FOR UPDATE;
SELECT * INTO r FROM agent_runs WHERE id = p_run_id FOR UPDATE;
SELECT * INTO s FROM agent_runtime_sessions WHERE id = a.session_id FOR UPDATE;
SELECT * INTO d FROM agent_action_dispatch_intents WHERE id = p_dispatch_intent_id FOR SHARE;
SELECT * INTO p FROM agent_policy_receipts WHERE id = d.policy_receipt_id FOR SHARE;
IF a.id IS NULL OR x.id IS NULL OR r.id IS NULL OR s.id IS NULL OR d.id IS NULL OR p.id IS NULL OR p.decision <> 'allow' OR p.expires_at <= clock_timestamp() OR p.action_id IS DISTINCT FROM x.id OR p.session_id IS DISTINCT FROM s.id OR p.run_id IS DISTINCT FROM r.id OR a.action_id IS DISTINCT FROM p_action_id OR a.run_id IS DISTINCT FROM p_run_id OR a.org_id IS DISTINCT FROM p_org_id OR a.user_id IS DISTINCT FROM p_user_id OR x.run_id IS DISTINCT FROM p_run_id OR x.org_id IS DISTINCT FROM p_org_id OR x.user_id IS DISTINCT FROM p_user_id OR r.session_id IS DISTINCT FROM a.session_id OR r.org_id IS DISTINCT FROM p_org_id OR r.user_id IS DISTINCT FROM p_user_id OR s.scope_kind IS DISTINCT FROM p_scope_kind OR s.scope_id IS DISTINCT FROM btrim(p_scope_id) OR a.execution_token IS DISTINCT FROM p_execution_token OR a.request_hash IS DISTINCT FROM p_request_hash OR a.state_version IS DISTINCT FROM p_attempt_state_version OR x.tool_name <> 'manage_scheduled_task' OR a.status NOT IN ('dispatching','accepted','unknown') OR r.status <> 'running' OR x.status <> 'running' OR a.status <> 'dispatching' OR d.attempt_id IS DISTINCT FROM a.id OR d.action_id IS DISTINCT FROM x.id OR d.execution_token IS DISTINCT FROM p_execution_token OR d.request_hash IS DISTINCT FROM p_request_hash OR d.executor_type <> 'runtime_scheduled_task:manage_scheduled_task' OR d.executor_revision <> 1 OR p.executor_type <> d.executor_type OR p.executor_revision <> d.executor_revision OR p.policy_revision <> d.policy_revision THEN RAISE EXCEPTION 'RUNTIME_SCHEDULER_CONTEXT_MISMATCH' USING ERRCODE = '42501';
END IF;
SELECT * INTO f FROM agent_runtime_owner_fences WHERE owner_kind = 'attempt' AND owner_id = a.id AND execution_token = a.execution_token FOR SHARE;
IF NOT FOUND THEN RAISE EXCEPTION 'RUNTIME_SCHEDULER_OWNER_FENCE_MISSING' USING ERRCODE = '42501';
END IF;
gate := _agent_runtime_kill_epoch_context( a.id, p_execution_token, p_request_hash, p_attempt_state_version, 'dispatch');
IF gate->>'outcome' <> 'allowed' THEN RAISE EXCEPTION '%', COALESCE(gate->>'error_code', 'RUNTIME_SCHEDULER_KILL_FENCED') USING ERRCODE = '42501';
END IF;
RETURN jsonb_build_object( 'session_id', s.id, 'run_id', r.id, 'action_id', x.id, 'attempt_id', a.id, 'policy_receipt_id', d.policy_receipt_id, 'tenant_kill_epoch', f.tenant_kill_epoch, 'provider_kill_epoch', f.provider_kill_epoch, 'capability_kill_epoch', f.capability_kill_epoch, 'provider_revision', f.provider_revision, 'capability_revision', f.capability_revision);
END;
$$;
CREATE FUNCTION _runtime_scheduler_response( p_outcome TEXT, p_receipt agent_runtime_scheduler_operation_receipts ) RETURNS JSONB LANGUAGE SQL SET search_path = pg_catalog, public AS $$ SELECT jsonb_build_object( 'outcome', p_outcome, 'receipt_outcome', p_receipt.outcome, 'receipt_id', p_receipt.id, 'intent_id', p_receipt.intent_id, 'task_id', p_receipt.task_id, 'state_version', p_receipt.state_version, 'task', p_receipt.task_snapshot, 'response_hash', p_receipt.response_hash);
$$;
CREATE FUNCTION _runtime_scheduler_schedule_hash(p_task scheduled_tasks) RETURNS TEXT LANGUAGE SQL IMMUTABLE SET search_path = pg_catalog, public AS $$ SELECT encode(digest(convert_to(jsonb_build_object('task_id',p_task.id,'state_version',p_task.runtime_state_version,'schedule_type',p_task.schedule_type,'cron_expr',p_task.cron_expr,'timezone',p_task.timezone,'run_at',p_task.run_at,'weekdays',p_task.weekdays,'day_of_month',p_task.day_of_month)::TEXT,'UTF8'),'sha256'),'hex'); $$;
CREATE FUNCTION get_agent_runtime_scheduled_task_resume_context_v1( p_attempt_id UUID,p_action_id UUID,p_run_id UUID,p_org_id UUID,p_user_id UUID,p_scope_kind TEXT,p_scope_id TEXT,p_task_id UUID,p_expected_state_version BIGINT,p_attempt_state_version BIGINT,p_request_hash TEXT,p_execution_token UUID,p_dispatch_intent_id UUID ) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$ DECLARE context JSONB; task scheduled_tasks%ROWTYPE; BEGIN context:=_runtime_scheduler_control_context(p_attempt_id,p_action_id,p_run_id,p_org_id,p_user_id,p_scope_kind,p_scope_id,p_request_hash,p_execution_token,p_attempt_state_version,p_dispatch_intent_id); SELECT * INTO task FROM scheduled_tasks WHERE id=p_task_id FOR SHARE; IF NOT FOUND OR task.org_id IS DISTINCT FROM p_org_id THEN RAISE EXCEPTION 'RUNTIME_SCHEDULER_TENANT_SCOPE_MISMATCH' USING ERRCODE='42501'; END IF; IF task.runtime_state_version IS DISTINCT FROM p_expected_state_version OR task.status<>'paused' THEN RAISE EXCEPTION 'RUNTIME_SCHEDULER_RESUME_STATE_CONFLICT' USING ERRCODE='40001'; END IF; IF NOT _runtime_scheduler_operation_allowed(p_org_id,p_user_id,'resume',task.user_id) THEN RAISE EXCEPTION 'RUNTIME_SCHEDULER_OPERATION_PERMISSION_DENIED' USING ERRCODE='42501'; END IF; IF task.schedule_type='once' AND task.run_at IS NULL OR task.schedule_type<>'once' AND (NULLIF(btrim(task.cron_expr),'') IS NULL OR NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=task.timezone)) THEN RAISE EXCEPTION 'RUNTIME_SCHEDULER_RESUME_SCHEDULE_INVALID' USING ERRCODE='22023'; END IF; RETURN jsonb_build_object('task_id',task.id,'state_version',task.runtime_state_version,'schedule_type',task.schedule_type,'cron_expr',task.cron_expr,'timezone',task.timezone,'run_at',task.run_at,'weekdays',task.weekdays,'day_of_month',task.day_of_month,'schedule_hash',_runtime_scheduler_schedule_hash(task),'calculation_revision','services.scheduler.cron_utils.calc_next_run:v1'); END; $$;
CREATE FUNCTION mutate_agent_runtime_scheduled_task_control_v1( p_attempt_id UUID, p_action_id UUID, p_run_id UUID, p_org_id UUID, p_user_id UUID, p_scope_kind TEXT, p_scope_id TEXT, p_task_id UUID, p_operation TEXT, p_expected_state_version BIGINT, p_attempt_state_version BIGINT, p_request_hash TEXT, p_execution_token UUID, p_idempotency_key TEXT, p_dispatch_intent_id UUID, p_payload JSONB, p_resume_schedule_hash TEXT, p_resume_next_run_at TIMESTAMPTZ ) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$ DECLARE context JSONB;
intent agent_runtime_scheduler_operation_intents%ROWTYPE;
receipt agent_runtime_scheduler_operation_receipts%ROWTYPE;
task scheduled_tasks%ROWTYPE;
old_task JSONB;
response_snapshot JSONB;
fields JSONB := COALESCE(p_payload, '{}'::JSONB);
payload_hash TEXT := encode(digest(convert_to(jsonb_build_object('payload',COALESCE(p_payload,'{}'::JSONB),'resume_schedule_hash',p_resume_schedule_hash,'resume_next_run_at',p_resume_next_run_at)::TEXT, 'UTF8'), 'sha256'), 'hex');
response_hash TEXT;
cancel_gate agent_runtime_scheduler_cancel_gates%ROWTYPE;
BEGIN IF p_operation NOT IN ('create','update','pause','resume','delete') OR p_task_id IS NULL OR p_expected_state_version IS NULL OR p_expected_state_version < 0 OR NULLIF(btrim(p_idempotency_key), '') IS NULL OR NOT _runtime_scheduler_payload_valid(p_operation, p_payload) OR (p_operation='resume' AND (p_resume_schedule_hash !~ '^[0-9a-f]{64}$' OR p_resume_next_run_at IS NULL OR p_resume_next_run_at<=clock_timestamp())) OR (p_operation<>'resume' AND (p_resume_schedule_hash IS NOT NULL OR p_resume_next_run_at IS NOT NULL)) THEN RAISE EXCEPTION 'RUNTIME_SCHEDULER_REQUEST_INVALID' USING ERRCODE = '22023';
END IF;
PERFORM pg_advisory_xact_lock(hashtextextended( 'runtime-scheduler-idempotency:' || p_org_id::TEXT || ':' || btrim(p_idempotency_key), 0));
context := _runtime_scheduler_control_context( p_attempt_id, p_action_id, p_run_id, p_org_id, p_user_id, p_scope_kind, p_scope_id, p_request_hash, p_execution_token, p_attempt_state_version, p_dispatch_intent_id);
SELECT * INTO cancel_gate FROM agent_runtime_scheduler_cancel_gates WHERE org_id = p_org_id AND idempotency_key = btrim(p_idempotency_key);
IF FOUND THEN IF cancel_gate.action_id IS DISTINCT FROM p_action_id OR cancel_gate.attempt_id IS DISTINCT FROM p_attempt_id OR cancel_gate.request_hash IS DISTINCT FROM p_request_hash THEN RAISE EXCEPTION 'RUNTIME_SCHEDULER_IDEMPOTENCY_CONFLICT' USING ERRCODE = '40001';
END IF;
RETURN jsonb_build_object( 'outcome', 'cancelled', 'cancel_confirmed', TRUE, 'cancel_gate_id', cancel_gate.id, 'proof_hash', cancel_gate.proof_hash);
END IF;
PERFORM pg_advisory_xact_lock(hashtextextended( 'runtime-scheduler-task:' || p_task_id::TEXT, 0));
SELECT * INTO intent FROM agent_runtime_scheduler_operation_intents WHERE org_id = p_org_id AND idempotency_key = btrim(p_idempotency_key) FOR UPDATE;
IF FOUND THEN IF intent.task_id IS DISTINCT FROM p_task_id OR intent.operation IS DISTINCT FROM p_operation OR intent.request_hash IS DISTINCT FROM p_request_hash OR intent.payload_hash IS DISTINCT FROM payload_hash OR intent.action_id IS DISTINCT FROM p_action_id OR intent.attempt_id IS DISTINCT FROM p_attempt_id THEN RAISE EXCEPTION 'RUNTIME_SCHEDULER_IDEMPOTENCY_CONFLICT' USING ERRCODE = '40001';
END IF;
SELECT * INTO receipt FROM agent_runtime_scheduler_operation_receipts WHERE intent_id = intent.id;
IF FOUND THEN RETURN _runtime_scheduler_response('readback', receipt);
END IF;
RETURN jsonb_build_object('outcome', 'reconcile_required', 'intent_id', intent.id);
END IF;
SELECT * INTO task FROM scheduled_tasks WHERE id = p_task_id FOR UPDATE;
IF task.id IS NOT NULL AND task.org_id IS DISTINCT FROM p_org_id THEN RAISE EXCEPTION 'RUNTIME_SCHEDULER_TENANT_SCOPE_MISMATCH' USING ERRCODE='42501'; END IF;
IF p_operation='create' THEN IF NOT _runtime_scheduler_actor_allowed(p_org_id,p_user_id,FALSE) THEN RAISE EXCEPTION 'RUNTIME_SCHEDULER_OPERATION_PERMISSION_DENIED' USING ERRCODE='42501'; END IF; ELSIF task.id IS NOT NULL AND NOT _runtime_scheduler_operation_allowed(p_org_id,p_user_id,p_operation,task.user_id) THEN RAISE EXCEPTION 'RUNTIME_SCHEDULER_OPERATION_PERMISSION_DENIED' USING ERRCODE='42501'; END IF;
IF fields ? 'push_target' AND NOT _runtime_scheduler_push_target_allowed(p_org_id,p_user_id,fields->'push_target') THEN RAISE EXCEPTION 'RUNTIME_SCHEDULER_PUSH_TARGET_DENIED' USING ERRCODE='42501'; END IF;
INSERT INTO agent_runtime_scheduler_operation_intents( task_id, org_id, user_id, session_id, run_id, action_id, attempt_id, policy_receipt_id, dispatch_intent_id, operation, expected_state_version, request_hash, payload_hash, idempotency_key, execution_token, tenant_kill_epoch, provider_kill_epoch, capability_kill_epoch, provider_revision, capability_revision ) VALUES ( p_task_id, p_org_id, p_user_id, (context->>'session_id')::UUID, p_run_id, p_action_id, p_attempt_id, (context->>'policy_receipt_id')::UUID, p_dispatch_intent_id, p_operation, p_expected_state_version, p_request_hash, payload_hash, btrim(p_idempotency_key), p_execution_token, (context->>'tenant_kill_epoch')::BIGINT, (context->>'provider_kill_epoch')::BIGINT, (context->>'capability_kill_epoch')::BIGINT, NULLIF(context->>'provider_revision', ''), NULLIF(context->>'capability_revision', '') ) RETURNING * INTO intent;
IF p_operation = 'create' THEN IF task.id IS NOT NULL AND ( task.org_id IS DISTINCT FROM p_org_id OR task.user_id IS DISTINCT FROM p_user_id ) THEN RAISE EXCEPTION 'RUNTIME_SCHEDULER_TENANT_SCOPE_MISMATCH' USING ERRCODE = '42501';
END IF;
IF task.id IS NOT NULL OR p_expected_state_version <> 0 OR NULLIF(btrim(fields->>'name'), '') IS NULL OR fields->>'prompt' IS NULL OR fields->'push_target' IS NULL THEN IF task.id IS NOT NULL THEN INSERT INTO agent_runtime_scheduler_operation_receipts( intent_id, outcome, task_id, state_version, task_snapshot, response_hash ) VALUES (intent.id, 'cas_conflict', p_task_id, task.runtime_state_version, to_jsonb(task), encode(digest(convert_to(to_jsonb(task)::TEXT, 'UTF8'), 'sha256'), 'hex')) RETURNING * INTO receipt;
RETURN _runtime_scheduler_response('cas_conflict', receipt);
END IF;
RAISE EXCEPTION 'RUNTIME_SCHEDULER_CREATE_PAYLOAD_INVALID' USING ERRCODE = '22023';
END IF;
IF COALESCE(fields->>'schedule_type', 'cron') NOT IN ('once', 'daily', 'weekly', 'monthly', 'cron') OR (COALESCE(fields->>'schedule_type', 'cron') = 'once' AND NULLIF(fields->>'run_at', '') IS NULL) OR (COALESCE(fields->>'schedule_type', 'cron') <> 'once' AND NULLIF(btrim(fields->>'cron_expr'), '') IS NULL) THEN RAISE EXCEPTION 'RUNTIME_SCHEDULER_SCHEDULE_PAYLOAD_INVALID' USING ERRCODE = '22023';
END IF;
INSERT INTO scheduled_tasks( id, org_id, user_id, name, prompt, cron_expr, timezone, push_target, template_file, status, max_credits, retry_count, timeout_sec, schedule_type, run_at, weekdays, day_of_month, next_run_at, runtime_action_id, runtime_attempt_id, runtime_request_hash, runtime_state_version, runtime_idempotency_key, updated_at ) VALUES ( p_task_id, p_org_id, p_user_id, fields->>'name', fields->>'prompt', fields->>'cron_expr', COALESCE(fields->>'timezone', 'Asia/Shanghai'), fields->'push_target', fields->'template_file', 'active', COALESCE((fields->>'max_credits')::INTEGER, 10), COALESCE((fields->>'retry_count')::SMALLINT, 1), COALESCE((fields->>'timeout_sec')::INTEGER, 180), COALESCE(fields->>'schedule_type', 'cron'), NULLIF(fields->>'run_at', '')::TIMESTAMPTZ, CASE WHEN jsonb_typeof(fields->'weekdays')='array' THEN ARRAY(SELECT value::SMALLINT FROM jsonb_array_elements_text(fields->'weekdays')) END, NULLIF(fields->>'day_of_month', '')::SMALLINT, NULLIF(fields->>'next_run_at', '')::TIMESTAMPTZ, p_action_id, p_attempt_id, p_request_hash, 1, btrim(p_idempotency_key), clock_timestamp() ) RETURNING * INTO task;
ELSE IF task.id IS NOT NULL AND task.org_id IS DISTINCT FROM p_org_id THEN RAISE EXCEPTION 'RUNTIME_SCHEDULER_TENANT_SCOPE_MISMATCH' USING ERRCODE = '42501';
END IF;
IF task.id IS NULL OR task.runtime_state_version IS DISTINCT FROM p_expected_state_version THEN INSERT INTO agent_runtime_scheduler_operation_receipts( intent_id, outcome, task_id, state_version, task_snapshot, response_hash ) VALUES (intent.id, 'cas_conflict', p_task_id, COALESCE(task.runtime_state_version, 0), CASE WHEN task.id IS NULL THEN jsonb_build_object('task_id', p_task_id) ELSE jsonb_build_object( 'task_id', task.id, 'status', task.status, 'state_version', task.runtime_state_version) END, encode(digest(convert_to( (CASE WHEN task.id IS NULL THEN jsonb_build_object('task_id', p_task_id) ELSE jsonb_build_object( 'task_id', task.id, 'status', task.status, 'state_version', task.runtime_state_version) END)::TEXT, 'UTF8'), 'sha256'), 'hex')) RETURNING * INTO receipt;
RETURN _runtime_scheduler_response('cas_conflict', receipt);
END IF;
old_task := to_jsonb(task);
IF p_operation = 'delete' THEN DELETE FROM scheduled_tasks WHERE id = p_task_id;
task := NULL;
ELSIF p_operation = 'pause' THEN UPDATE scheduled_tasks SET status = 'paused', next_run_at=NULL, runtime_action_id = p_action_id, runtime_attempt_id = p_attempt_id, runtime_request_hash = p_request_hash, runtime_state_version = runtime_state_version + 1, runtime_idempotency_key = btrim(p_idempotency_key), updated_at = clock_timestamp() WHERE id = p_task_id RETURNING * INTO task;
ELSIF p_operation = 'resume' THEN IF task.status<>'paused' OR _runtime_scheduler_schedule_hash(task) IS DISTINCT FROM p_resume_schedule_hash OR (task.schedule_type='once' AND task.run_at IS DISTINCT FROM p_resume_next_run_at) THEN RAISE EXCEPTION 'RUNTIME_SCHEDULER_RESUME_FENCED' USING ERRCODE='40001'; END IF; UPDATE scheduled_tasks SET status = 'active', next_run_at=p_resume_next_run_at, consecutive_failures=0, runtime_action_id = p_action_id, runtime_attempt_id = p_attempt_id, runtime_request_hash = p_request_hash, runtime_state_version = runtime_state_version + 1, runtime_idempotency_key = btrim(p_idempotency_key), updated_at = clock_timestamp() WHERE id = p_task_id RETURNING * INTO task;
ELSE UPDATE scheduled_tasks SET name = CASE WHEN fields ? 'name' THEN fields->>'name' ELSE name END, prompt = CASE WHEN fields ? 'prompt' THEN fields->>'prompt' ELSE prompt END, cron_expr = CASE WHEN fields ? 'cron_expr' THEN NULLIF(fields->>'cron_expr', '') ELSE cron_expr END, timezone = CASE WHEN fields ? 'timezone' THEN fields->>'timezone' ELSE timezone END, push_target = CASE WHEN fields ? 'push_target' THEN fields->'push_target' ELSE push_target END, template_file = CASE WHEN fields ? 'template_file' THEN fields->'template_file' ELSE template_file END, max_credits = CASE WHEN fields ? 'max_credits' THEN (fields->>'max_credits')::INTEGER ELSE max_credits END, retry_count = CASE WHEN fields ? 'retry_count' THEN (fields->>'retry_count')::SMALLINT ELSE retry_count END, timeout_sec = CASE WHEN fields ? 'timeout_sec' THEN (fields->>'timeout_sec')::INTEGER ELSE timeout_sec END, schedule_type = CASE WHEN fields ? 'schedule_type' THEN fields->>'schedule_type' ELSE schedule_type END, run_at = CASE WHEN fields ? 'run_at' THEN NULLIF(fields->>'run_at', '')::TIMESTAMPTZ ELSE run_at END, weekdays = CASE WHEN jsonb_typeof(fields->'weekdays')='array' THEN ARRAY(SELECT value::SMALLINT FROM jsonb_array_elements_text(fields->'weekdays')) WHEN fields ? 'weekdays' THEN NULL ELSE weekdays END, day_of_month = CASE WHEN fields ? 'day_of_month' THEN NULLIF(fields->>'day_of_month', '')::SMALLINT ELSE day_of_month END, next_run_at = CASE WHEN fields ? 'next_run_at' THEN NULLIF(fields->>'next_run_at', '')::TIMESTAMPTZ ELSE next_run_at END, runtime_action_id = p_action_id, runtime_attempt_id = p_attempt_id, runtime_request_hash = p_request_hash, runtime_state_version = runtime_state_version + 1, runtime_idempotency_key = btrim(p_idempotency_key), updated_at = clock_timestamp() WHERE id = p_task_id RETURNING * INTO task;
END IF;
END IF;
PERFORM _agent_runtime_226_append_action_event( p_action_id, 'scheduler.task.committed', jsonb_build_object('task_id', p_task_id, 'operation', p_operation, 'state_version', CASE WHEN p_operation = 'delete' THEN p_expected_state_version + 1 ELSE task.runtime_state_version END));
response_snapshot := jsonb_build_object( 'task_id', p_task_id, 'operation', p_operation, 'status', CASE WHEN p_operation = 'delete' THEN 'deleted' ELSE task.status END, 'state_version', CASE WHEN p_operation = 'delete' THEN p_expected_state_version + 1 ELSE task.runtime_state_version END, 'deleted', p_operation = 'delete');
response_hash := encode(digest(convert_to(response_snapshot::TEXT, 'UTF8'), 'sha256'), 'hex');
INSERT INTO agent_runtime_scheduler_operation_receipts( intent_id, outcome, task_id, state_version, task_snapshot, response_hash ) VALUES ( intent.id, 'committed', p_task_id, CASE WHEN p_operation = 'delete' THEN p_expected_state_version + 1 ELSE task.runtime_state_version END, COALESCE(response_snapshot, jsonb_build_object('task_id', p_task_id, 'deleted', TRUE)), response_hash ) RETURNING * INTO receipt;
RETURN _runtime_scheduler_response('committed', receipt);
END;
$$;
CREATE FUNCTION read_agent_runtime_scheduled_task_control_v1( p_attempt_id UUID, p_request_hash TEXT, p_execution_token UUID, p_expected_state_version BIGINT, p_idempotency_key TEXT ) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$ DECLARE receipt agent_runtime_scheduler_operation_receipts%ROWTYPE;
cancel_gate agent_runtime_scheduler_cancel_gates%ROWTYPE;
BEGIN PERFORM _assert_agent_runtime_actor(TRUE);
SELECT rct.* INTO receipt FROM agent_runtime_scheduler_operation_receipts rct JOIN agent_runtime_scheduler_operation_intents intent ON intent.id = rct.intent_id JOIN agent_action_attempts attempt ON attempt.id = intent.attempt_id WHERE intent.attempt_id = p_attempt_id AND intent.request_hash = p_request_hash AND intent.idempotency_key = btrim(p_idempotency_key) AND attempt.state_version = p_expected_state_version AND ((attempt.status='dispatching' AND attempt.execution_token=p_execution_token AND attempt.lease_expires_at>clock_timestamp()) OR (attempt.status IN ('accepted','unknown') AND attempt.reconciliation_token=p_execution_token AND attempt.reconciliation_lease_expires_at>clock_timestamp())) ORDER BY rct.created_at DESC LIMIT 1;
IF NOT FOUND THEN SELECT gate.* INTO cancel_gate FROM agent_runtime_scheduler_cancel_gates gate JOIN agent_action_attempts attempt ON attempt.id=gate.attempt_id WHERE gate.attempt_id=p_attempt_id AND gate.request_hash=p_request_hash AND gate.idempotency_key=btrim(p_idempotency_key) AND attempt.state_version=p_expected_state_version AND ((attempt.status='dispatching' AND attempt.execution_token=p_execution_token AND attempt.lease_expires_at>clock_timestamp()) OR (attempt.status IN ('accepted','unknown') AND attempt.reconciliation_token=p_execution_token AND attempt.reconciliation_lease_expires_at>clock_timestamp()));
IF NOT FOUND THEN RETURN jsonb_build_object('outcome','not_found');
END IF;
RETURN jsonb_build_object('outcome','cancelled','cancel_confirmed',TRUE, 'cancel_gate_id',cancel_gate.id,'proof_hash',cancel_gate.proof_hash);
END IF;
RETURN _runtime_scheduler_response('readback', receipt);
END;
$$;
CREATE FUNCTION cancel_agent_runtime_scheduled_task_control_v1( p_attempt_id UUID, p_request_hash TEXT, p_execution_token UUID, p_expected_state_version BIGINT, p_idempotency_key TEXT, p_reason TEXT DEFAULT 'runtime_cancel') RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$ DECLARE intent agent_runtime_scheduler_operation_intents%ROWTYPE;
receipt agent_runtime_scheduler_operation_receipts%ROWTYPE;
attempt agent_action_attempts%ROWTYPE;
cancel_gate agent_runtime_scheduler_cancel_gates%ROWTYPE;
proof TEXT;
BEGIN PERFORM _assert_agent_runtime_actor(TRUE);
SELECT * INTO attempt FROM agent_action_attempts WHERE id=p_attempt_id;
IF NOT FOUND OR attempt.request_hash IS DISTINCT FROM p_request_hash THEN RETURN jsonb_build_object('outcome', 'not_found');
END IF;
PERFORM pg_advisory_xact_lock(hashtextextended( 'runtime-scheduler-idempotency:' || attempt.org_id::TEXT || ':' || btrim(p_idempotency_key), 0));
SELECT * INTO attempt FROM agent_action_attempts WHERE id=p_attempt_id FOR UPDATE;
IF attempt.state_version IS DISTINCT FROM p_expected_state_version OR NOT ( (attempt.status='dispatching' AND attempt.execution_token=p_execution_token AND attempt.lease_expires_at>clock_timestamp()) OR (attempt.status IN ('accepted','unknown') AND attempt.reconciliation_token=p_execution_token AND attempt.reconciliation_lease_expires_at>clock_timestamp()) ) THEN RAISE EXCEPTION 'RUNTIME_SCHEDULER_CANCEL_FENCED' USING ERRCODE='42501';
END IF;
SELECT * INTO cancel_gate FROM agent_runtime_scheduler_cancel_gates WHERE org_id=attempt.org_id AND idempotency_key=btrim(p_idempotency_key);
IF FOUND THEN IF cancel_gate.attempt_id IS DISTINCT FROM p_attempt_id OR cancel_gate.request_hash IS DISTINCT FROM p_request_hash THEN RAISE EXCEPTION 'RUNTIME_SCHEDULER_IDEMPOTENCY_CONFLICT' USING ERRCODE='40001';
END IF;
RETURN jsonb_build_object('outcome','cancelled','cancel_confirmed',TRUE, 'cancel_gate_id',cancel_gate.id,'proof_hash',cancel_gate.proof_hash);
END IF;
SELECT operation_intent.* INTO intent FROM agent_runtime_scheduler_operation_intents operation_intent WHERE operation_intent.attempt_id = p_attempt_id AND operation_intent.request_hash = p_request_hash AND operation_intent.idempotency_key = btrim(p_idempotency_key) FOR UPDATE;
IF FOUND THEN SELECT * INTO receipt FROM agent_runtime_scheduler_operation_receipts WHERE intent_id = intent.id;
IF FOUND THEN RETURN _runtime_scheduler_response('committed_readback', receipt);
END IF;
END IF;
proof := encode(digest(convert_to(jsonb_build_object( 'attempt_id',p_attempt_id,'request_hash',p_request_hash, 'idempotency_key',btrim(p_idempotency_key), 'reason',LEFT(COALESCE(p_reason,'runtime_cancel'),200) )::TEXT,'UTF8'),'sha256'),'hex');
INSERT INTO agent_runtime_scheduler_cancel_gates( org_id,action_id,attempt_id,request_hash,idempotency_key,reason,proof_hash ) VALUES (attempt.org_id,attempt.action_id,attempt.id,p_request_hash, btrim(p_idempotency_key),LEFT(COALESCE(p_reason,'runtime_cancel'),200),proof) RETURNING * INTO cancel_gate;
RETURN jsonb_build_object('outcome','cancelled','cancel_confirmed',TRUE, 'cancel_gate_id',cancel_gate.id,'proof_hash',cancel_gate.proof_hash);
END;
$$;
CREATE FUNCTION reconcile_agent_runtime_scheduled_task_control_v1( p_attempt_id UUID, p_request_hash TEXT, p_execution_token UUID, p_expected_state_version BIGINT, p_idempotency_key TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$ BEGIN RETURN read_agent_runtime_scheduled_task_control_v1( p_attempt_id, p_request_hash, p_execution_token, p_expected_state_version, p_idempotency_key);
END;
$$;
REVOKE ALL ON FUNCTION _runtime_scheduler_immutable_fact(), _runtime_scheduler_actor_allowed(UUID,UUID,BOOLEAN), _runtime_scheduler_operation_allowed(UUID,UUID,TEXT,UUID), _runtime_scheduler_push_target_allowed(UUID,UUID,JSONB,INTEGER), _runtime_scheduler_payload_safe(JSONB), _runtime_scheduler_payload_valid(TEXT,JSONB), _runtime_scheduler_control_context(UUID,UUID,UUID,UUID,UUID,TEXT,TEXT,TEXT,UUID,BIGINT,UUID), _runtime_scheduler_response(TEXT,agent_runtime_scheduler_operation_receipts), _runtime_scheduler_schedule_hash(scheduled_tasks), get_agent_runtime_scheduled_task_resume_context_v1(UUID,UUID,UUID,UUID,UUID,TEXT,TEXT,UUID,BIGINT,BIGINT,TEXT,UUID,UUID), mutate_agent_runtime_scheduled_task_control_v1(UUID,UUID,UUID,UUID,UUID,TEXT,TEXT,UUID,TEXT,BIGINT,BIGINT,TEXT,UUID,TEXT,UUID,JSONB,TEXT,TIMESTAMPTZ), read_agent_runtime_scheduled_task_control_v1(UUID,TEXT,UUID,BIGINT,TEXT), cancel_agent_runtime_scheduled_task_control_v1(UUID,TEXT,UUID,BIGINT,TEXT,TEXT), reconcile_agent_runtime_scheduled_task_control_v1(UUID,TEXT,UUID,BIGINT,TEXT) FROM PUBLIC, everydayai_runtime, everydayai_wecom_runtime, everydayai_worker, everydayai_sync, everydayai;
GRANT EXECUTE ON FUNCTION get_agent_runtime_scheduled_task_resume_context_v1(UUID,UUID,UUID,UUID,UUID,TEXT,TEXT,UUID,BIGINT,BIGINT,TEXT,UUID,UUID), mutate_agent_runtime_scheduled_task_control_v1(UUID,UUID,UUID,UUID,UUID,TEXT,TEXT,UUID,TEXT,BIGINT,BIGINT,TEXT,UUID,TEXT,UUID,JSONB,TEXT,TIMESTAMPTZ), read_agent_runtime_scheduled_task_control_v1(UUID,TEXT,UUID,BIGINT,TEXT), cancel_agent_runtime_scheduled_task_control_v1(UUID,TEXT,UUID,BIGINT,TEXT,TEXT), reconcile_agent_runtime_scheduled_task_control_v1(UUID,TEXT,UUID,BIGINT,TEXT) TO everydayai_agent_runtime_worker;
REVOKE EXECUTE ON FUNCTION runtime_mutate_scheduled_task(UUID,UUID,UUID,BIGINT,TEXT,TEXT,JSONB,UUID) FROM PUBLIC, everydayai_runtime, everydayai_wecom_runtime, everydayai_worker, everydayai_sync, everydayai, everydayai_agent_runtime_worker;
RESET ROLE;
